			"PowerPoint.ColorScheme": {"displayName":"ColorScheme","members":[{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"Returns an Application object that represents the creator of the specified object.","params":[],"source":"external"}},{"name":"Colors","kind":"method","returns":"PowerPoint.RGBColor","signature":"Colors(SchemeColor As PpColorSchemeIndex) As RGBColor","doc":{"summary":"Returns an RGBColor object that represents a single color in a color scheme.","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Returns the number of objects in the specified collection. Read-only.","params":[],"source":"external"}},{"name":"Delete","kind":"method","signature":"Delete()","doc":{"summary":"Deletes the specified ColorScheme object.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent object for the specified object.","params":[],"source":"external"}}],"provenance":"Represents a color scheme, which is a set of eight colors used for the different elements of a slide, notes page, or handout, such as the title or background. (Note that the color schemes for slides, notes pages, and handouts in a presentation can be set independently.)"},
			"PowerPoint.ColorSchemes": {"displayName":"ColorSchemes","members":[{"name":"Add","kind":"method","returns":"PowerPoint.ColorScheme","signature":"Add([Scheme As ColorScheme]) As ColorScheme","doc":{"summary":"Adds a color scheme to the collection of available schemes. Returns a ColorScheme object that represents the added color scheme.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"Returns an Application object that represents the creator of the specified object.","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Returns the number of objects in the specified collection. Read-only.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"PowerPoint.ColorScheme","signature":"Item(Index As Long) As ColorScheme","doc":{"summary":"Returns a single ColorScheme object from the specified ColorSchemes collection.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent object for the specified object.","params":[],"source":"external"}}],"provenance":"A collection of all the ColorScheme objects in the specified presentation. Each ColorScheme object represents a color scheme, which is a set of colors that are used together on a slide."},
