			"PowerPoint.EffectParameters": {"displayName":"EffectParameters","members":[{"name":"Amount","kind":"property","returns":"Single","doc":{"summary":"Returns or sets a Single that represents the number of degrees an animated shape is rotated around the z-axis. A positive value indicates clockwise rotation; a negative value indicates counterclockwise rotation. Read/write.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"Returns an Application object that represents the creator of the specified object.","params":[],"source":"external"}},{"name":"Color2","kind":"property","returns":"PowerPoint.ColorFormat","doc":{"summary":"Returns a ColorFormat object that represents the color on which to end a color-cycle animation.","params":[],"source":"external"}},{"name":"Direction","kind":"property","returns":"MsoAnimDirection","doc":{"summary":"Determines the direction used for an animation effect. This property can be used only if the effect uses a direction. Read/write.","params":[],"source":"external"}},{"name":"FontName","kind":"property","returns":"String","doc":{"summary":"Returns or sets the name of the font in the specified WordArt. Read/write.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent object for the specified object.","params":[],"source":"external"}},{"name":"Relative","kind":"property","returns":"MsoTriState","doc":{"summary":"Determines whether to set the motion position relative to the position of the shape. Read/write.","params":[],"source":"external"}},{"name":"Size","kind":"property","returns":"Single","doc":{"summary":"Returns or sets the character size, in points. Read/write.","params":[],"source":"external"}}],"provenance":"Represents various animation parameters for an Effect object, such as colors, fonts, sizes, and directions."},
