			"PowerPoint.ExtraColors": {"displayName":"ExtraColors","members":[{"name":"Add","kind":"method","signature":"Add(Type As MsoRGBType)","doc":{"summary":"Adds a color to the extra colors available to a presentation, if the color hasn't already been added.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"Returns an Application object that represents the creator of the specified object.","params":[],"source":"external"}},{"name":"Clear","kind":"method","signature":"Clear()","doc":{"summary":"Clears the extra colors in a presentation.","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Returns the number of objects in the specified collection. Read-only.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"MsoRGBType","signature":"Item(Index As Long) As MsoRGBType","doc":{"summary":"Returns a single color from the specified ExtraColors collection.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent object for the specified object.","params":[],"source":"external"}}],"provenance":"Represents the extra colors in a presentation. The object can contain up to eight colors, each of which is represented by an red-green-blue (RGB) value."},
			"PowerPoint.FileConverter": {"displayName":"FileConverter","members":[{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"Returns an Application object that represents the Microsoft PowerPoint application.","params":[],"source":"external"}},{"name":"CanOpen","kind":"property","returns":"Boolean","doc":{"summary":"True if the specified file converter is designed to open files. Read-only Boolean.","params":[],"source":"external"}},{"name":"CanSave","kind":"property","returns":"Boolean","doc":{"summary":"True if the specified file converter is designed to save files. Read-only Boolean.","params":[],"source":"external"}},{"name":"ClassName","kind":"property","returns":"String","doc":{"summary":"Returns a unique name that identifies the file converter. Read-only String.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"PowerPoint.FileConverters","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Extensions","kind":"property","returns":"String","doc":{"summary":"Returns the file name extensions associated with the specified FileConverter object. Read-only String.","params":[],"source":"external"}},{"name":"FormatName","kind":"property","returns":"String","doc":{"summary":"Returns the name of the specified file converter. Read-only String.","params":[],"source":"external"}},{"name":"Name","kind":"property","returns":"String","doc":{"summary":"Returns the name of the specified object. Read-only String.","params":[],"source":"external"}},{"name":"OpenFormat","kind":"property","returns":"Long","doc":{"summary":"Returns the file format of the specified file converter. Read-only Long.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"PowerPoint.FileConverters","doc":{"summary":"Returns an Object that represents the parent object of the specified FileConverter object.","params":[],"source":"external"}},{"name":"Path","kind":"property","returns":"String","doc":{"summary":"Returns the disk or Web path to the specified object. Read-only String.","params":[],"source":"external"}},{"name":"SaveFormat","kind":"property","returns":"Long","doc":{"summary":"Returns the file format of the specified document or file converter. Read-only Long.","params":[],"source":"external"}}],"provenance":"Represents a file converter that is used to open or save files. The FileConverter object is a member of the FileConverters collection. The FileConverters collection contains all the installed file converters for opening and saving files."},
