			"PowerPoint.Points": {"displayName":"Points","members":[{"name":"Application","kind":"property","returns":"PowerPoint.Application","doc":{"summary":"When used without an object qualifier, returns an Application object that represents the Microsoft PowerPoint application. When used with an object qualifier, returns an Application object that represents the creator of the specified object (you can use this property with an Automation object to re…","params":[],"source":"external"}},{"name":"Count","kind":"property","returns":"Long","doc":{"summary":"Returns the number of objects in the collection. Read-only Long.","params":[],"source":"external"}},{"name":"Creator","kind":"property","returns":"Long","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"PowerPoint.Point","signature":"Item(Index As Long) As Point","doc":{"summary":"Returns a single object from a collection.","params":[],"source":"external"}},{"name":"Parent","kind":"property","returns":"Object","doc":{"summary":"Returns the parent for the specified object. Read-only Object.","params":[],"source":"external"}}],"provenance":"A collection of all the Point objects in the specified series in a chart."},
